@startuml
class EBike {
  + bikeId : int
  + brand : string
  + model : string
}

class Frame {
  + material : string
  + frameId : int
}

class DriveSystem {
  + driveType : string
}

class Motor {
  + powerOutput : int
  + motorId : int
}

class Controller {
  + state : ControllerState
  + controlBattery() : void
  + commandDriveSystem() : void
}

class BasicController {}

class AdvancedController {
  + nextMaintenanceDate : date
  + estimateMaintenance() : date
}

class Battery {
  + storedEnergyWh : int
  + capacity : int
}

class Wheel {
  + wheelSize : int
  + wheelId : int
}

enum ControllerState {
  On
  Off
  Charging
}

EBike "1" *-- "1" Frame
EBike "1" *-- "1" DriveSystem
EBike "1" *-- "1" Controller
EBike "0..1" o-- "1" Battery
Frame "1" *-- "2" Wheel
DriveSystem "1" *-- "1" Motor
Controller "1" -- "0..1" Battery
Controller "1" -- "1" DriveSystem
BasicController --|> Controller
AdvancedController --|> Controller
@enduml

